// The weight of an item (tenths), or -1 when the table does not know it.
int embedded_item_weight(std::uint32_t nameid) {
    const std::uint32_t* end = kItemWeightIds + sizeof(kItemWeightIds) / sizeof(kItemWeightIds[0]);
    const std::uint32_t* it = std::lower_bound(kItemWeightIds, end, nameid);
    if (it == end || *it != nameid) return -1;
    return kItemWeights[it - kItemWeightIds];
}

